const C = $('Config').first().json; const CI = $('Config').all(); const ins = $input.all();
const strip = s => { s = String(s == null ? '' : s); return s.charAt(0) === "'" ? s.slice(1) : s; };
const byP = {}; const other = [];
for (let i = 0; i < ins.length; i++) { const tab = CI[i].json.TAB; const isos = CI[i].json.ISOS; const v = ins[i].json.values || []; const H = v[0] || [];
  const col = n => H.indexOf(n); const ci = { p: col('Project'), k: col('Key'), cur: col('Current translation'), prop: col('Proposed (linguist version)') };
  if (ci.p < 0 || ci.k < 0 || ci.cur < 0 || ci.prop < 0) { other.push({ tab: tab, a: 'bad header', H: H.join('|').slice(0, 200) }); continue; }
  for (let r = 1; r < v.length; r++) { const row = v[r] || []; const p = String(row[ci.p] || '').trim(); const k = String(row[ci.k] || '').trim(); if (!p || !k) continue;
    const o = { tab: tab, isos: isos, r: r + 1, p: p, k: k, cur: strip(row[ci.cur]), prop: strip(row[ci.prop]) };
    const pid = C.PIDS[p]; if (!pid) { other.push({ tab: tab, r: o.r, p: p, k: k, a: 'NO PID' }); continue; }
    (byP[pid] = byP[pid] || []).push(o); } }
$getWorkflowStaticData('global').other = other;
const out = [];
for (const pid of Object.keys(byP)) { const keys = Array.from(new Set(byP[pid].map(x => x.k)));
  for (let j = 0; j < keys.length; j += 60) { const ch = keys.slice(j, j + 60); const set = new Set(ch);
    out.push({ json: { pid: pid, rows: byP[pid].filter(x => set.has(x.k)), url: 'https://api.lokalise.com/api2/projects/' + pid + '/keys?include_translations=1&disable_references=1&filter_archived=exclude&limit=500&filter_keys=' + encodeURIComponent(ch.join(',')) } }); } }
return out;

const C = $('Config').first().json; const P = $('Plan').all(); const F = $input.all();
const kn = k => { const n = k.key_name || {}; return typeof n === 'string' ? n : (n.web || n.other || n.ios || n.android || ''); };
const out = []; const report = [];
for (let i = 0; i < P.length; i++) { const pid = P[i].json.pid; const b = (F[i] && F[i].json.body) || {}; if (!Array.isArray(b.keys)) continue;
  for (const o of P[i].json.rows) { const id = o.tab + '|' + o.p + '|' + o.k; const rv = C.REVERT[id]; if (!rv) continue;
    const k = b.keys.find(x => kn(x) === o.k); if (!k) { report.push({ id, a: 'key not found' }); continue; }
    const t = (k.translations || []).find(x => o.isos.includes(x.language_iso)); if (!t) { report.push({ id, a: 'no slot' }); continue; }
    if (t.translation !== rv.from) { report.push({ id, a: 'live differs', live: t.translation }); continue; }
    out.push({ json: { pid: pid, tid: t.translation_id, k: o.k, p: o.p, tab: o.tab, want: rv.to, plural: false, body: { translation: rv.to } } }); report.push({ id, a: 'revert' }); } }
$getWorkflowStaticData('global').sum = report;
if (!out.length) return [{ json: { none: true, report } }];
return out;

const res = $input.all(); const req = $('Build').all();
if (req.length && req[0].json.none) return [req[0].json];
let ok = 0; const bad = []; const byTab = {};
for (let i = 0; i < res.length; i++) { const r = res[i].json; const q = req[i].json;
  const got = r.body && r.body.translation ? r.body.translation.translation : undefined;
  let same = false; if (q.plural) { try { same = JSON.stringify(typeof got === 'string' ? JSON.parse(got) : got) === JSON.stringify(JSON.parse(q.want)); } catch (e) {} } else same = got === q.want;
  if (r.statusCode === 200 && same) { ok++; byTab[q.tab] = (byTab[q.tab] || 0) + 1; } else bad.push({ tab: q.tab, p: q.p, k: q.k, status: r.statusCode, got: String(got).slice(0, 200), err: JSON.stringify((r.body && r.body.error) || r.error || '').slice(0, 200) }); }
const sd = $getWorkflowStaticData('global');
return [{ json: { written_ok: ok, byTab: byTab, bad: bad, sum: sd.sum } }];
